#include <stdio.h>
#include <string.h>
int main() {
    char s[1000];
    if (!fgets(s, sizeof(s), stdin)) return 0;
    int counts[256] = {0};
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    for (int i = 0; i < len; i++) {
        if (s[i] != ' ') counts[(unsigned char)s[i]]++;
    }
    int max_c = 0; char best = '\0';
    for (int i = 0; i < len; i++) {
        if (s[i] != ' ' && counts[(unsigned char)s[i]] > max_c) {
            max_c = counts[(unsigned char)s[i]];
            best = s[i];
        }
    }
    if (best) printf("%c:%d\n", best, max_c);
    return 0;
}

