#include <unordered_map>
using namespace std;
int main() {
    string s;
    if (!getline(cin, s)) return 0;
    unordered_map<char, int> cnt;
    for (char c : s) if (c != ' ') cnt[c]++;
    int max_val = 0; char best = '\0';
    for (char c : s) {
        if (c != ' ' && cnt[c] > max_val) {
            max_val = cnt[c];
            best = c;
        }
    }
    if (best) cout << best << ":" << max_val << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.HashMap;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine();
            HashMap<Character, Integer> cnt = new HashMap<>();
            for (char c : s.toCharArray()) if (c != ' ') cnt.put(c, cnt.getOrDefault(c, 0) + 1);
            int max_val = 0; char best = '\0';
            for (char c : s.toCharArray()) {
                if (c != ' ' && cnt.get(c) > max_val) {
                    max_val = cnt.get(c);
                    best = c;
                }
            }
            if (best != '\0') System.out.println(best + ":" + max_val);
        }
    }
}

